      border: 1px solid var(--line);
      border-inline-end: 0;
      border-radius: var(--radius-md) 0 0 var(--radius-md);
      font-weight: 600;
    }

    .phone-wrap input {
      border-radius: 0 var(--radius-md) var(--radius-md) 0;
      text-align: left;
    }

    .hint {
      margin: 7px 2px 0;
      color: var(--muted);
      font-size: 14px;
    }

    .makani-row {
      display: grid;
      grid-template-columns: minmax(0, 1fr) 132px;
      gap: 10px;
    }

    .map-button {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 7px;
      min-height: 54px;
      padding: 0 12px;
      color: var(--primary);
      background: var(--primary-soft);
      border: 1px solid #cbe4d7;
      border-radius: var(--radius-md);
      font-size: 14px;
      font-weight: 600;
      cursor: pointer;
    }

    .map-button svg {
      width: 19px;
      height: 19px;
    }

    .save-button {
      width: 100%;
      min-height: 56px;
      margin-top: 24px;
      padding: 12px 20px;
      color: #fff;
      background: var(--primary);
      border: 0;
      border-radius: var(--radius-md);
      box-shadow: 0 10px 22px rgba(23, 107, 74, 0.2);
      font-size: 16px;
      font-weight: 700;
      cursor: pointer;
      transition: background 160ms ease, transform 160ms ease, box-shadow 160ms ease;
    }

    .save-button:hover {
      background: var(--primary-dark);
      box-shadow: 0 12px 26px rgba(23, 107, 74, 0.25);
    }

    .save-button:active {
      transform: translateY(1px);
    }

    .privacy-note {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 7px;
      margin: 14px 0 0;
      color: var(--muted);
      font-size: 14px;
      text-align: center;
    }

    .privacy-note svg {
      width: 16px;
      height: 16px;
      flex: 0 0 auto;
    }

    .toast {
      position: fixed;
      z-index: 10;
      inset-inline: 20px;
      bottom: 22px;
      max-width: 440px;
      margin: auto;
      padding: 14px 18px;
      color: #fff;
      background: #17372b;
      border-radius: 14px;
      box-shadow: 0 12px 30px rgba(0, 0, 0, 0.18);
      font-size: 14px;
      text-align: center;
      opacity: 0;
      transform: translateY(18px);
      pointer-events: none;
      transition: opacity 180ms ease, transform 180ms ease;
    }

    .toast.show {
      opacity: 1;
      transform: translateY(0);
    }

    @media (max-width: 370px) {
      .page {
        padding-inline: 12px;
      }

      .form-card {
        padding-inline: 16px;
      }

      .makani-row {
        grid-template-columns: 1fr;
      }
    }
  </style>
</head>
