  <script>
    const form = document.getElementById('addressForm');
    const toast = document.getElementById('toast');
    const locateButton = document.getElementById('locateButton');
    const makaniInput = document.getElementById('makani');

    function showToast(message) {
      toast.textContent = message;
      toast.classList.add('show');
      window.clearTimeout(showToast.timer);
      showToast.timer = window.setTimeout(() => toast.classList.remove('show'), 3200);
    }

    form.addEventListener('submit', function (event) {
      event.preventDefault();

      if (!form.checkValidity()) {
        form.reportValidity();
        return;
      }

      const phone = document.getElementById('phone');
      const digits = phone.value.replace(/\D/g, '');
      if (digits.length < 9 || digits.length > 12) {
        phone.setCustomValidity('أدخل رقم هاتف إماراتي صحيحًا');
        phone.reportValidity();
        return;
      }

      phone.setCustomValidity('');
      showToast('تم حفظ عنوان التوصيل بنجاح');
    });

    document.getElementById('phone').addEventListener('input', function (event) {
      event.target.setCustomValidity('');
    });

    locateButton.addEventListener('click', function () {
      if (!navigator.geolocation) {
        showToast('تحديد الموقع غير متاح في هذا الجهاز');
        return;
      }

      locateButton.disabled = true;
      locateButton.textContent = 'جارٍ التحديد...';

      navigator.geolocation.getCurrentPosition(
        function (position) {
          locateButton.disabled = false;
          locateButton.innerHTML = `
            <svg viewBox="0 0 24 24" fill="none" aria-hidden="true">
              <path d="m5 12 4 4L19 6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
            </svg>
            تم تحديد الموقع`;
          showToast('تم تحديد موقعك. يرجى مراجعة رقم-location مقهى');
        },
        function () {
          locateButton.disabled = false;
          locateButton.innerHTML = `
            <svg viewBox="0 0 24 24" fill="none" aria-hidden="true">
              <circle cx="12" cy="12" r="3" stroke="currentColor" stroke-width="1.8"/>
              <path d="M12 2v3M12 19v3M2 12h3M19 12h3" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/>
              <circle cx="12" cy="12" r="8" stroke="currentColor" stroke-width="1.8"/>
            </svg>
            حدد موقعك`;
          showToast('تعذر تحديد الموقع. اسمح بالوصول إلى الموقع وحاول مجددًا');
        },
        { enableHighAccuracy: true, timeout: 10000 }
      );
    });
  </script>
